package com.heavendoor.ultralab;
import android.content.*;import android.content.pm.PackageManager;import android.os.*;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import rikka.shizuku.Shizuku;

/** Process-owned native canvas and read-only data; independent of the foreground page. */
public final class UltraEngine {
 private static UltraEngine instance;
 public static synchronized UltraEngine get(Context c){if(instance==null)instance=new UltraEngine(c.getApplicationContext());return instance;}
 public static synchronized UltraEngine peek(){return instance;}
 public final UltraDashboardView dashboard;private final Context context;private FactoryRootClient rootReader;private volatile boolean restartRequested;
 private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private final AtomicBoolean pending=new AtomicBoolean();
 private final UltraCoverLoader covers;private final Shizuku.UserServiceArgs args;private final UltraFrameServer frames;private IUltraDataService reader;private volatile boolean started,closed;private boolean bound;private final UltraFrameHealth outputHealth=new UltraFrameHealth();private volatile long generation;private long received,nextBindAt;private volatile boolean projectionEnabled;private volatile int projectionMode;
 private String latest="{\"schema\":1,\"source\":\"vehicle\",\"connected\":false,\"fields\":{}}";
 public volatile String status="点击授权并读取";private volatile String projectionState="";
 private final Shizuku.OnBinderReceivedListener arrived=()->main.post(()->{if(started&&!closed){nextBindAt=0;bind();}});
 private final Shizuku.OnBinderDeadListener died=()->main.post(()->{if(rootReader==null){release();empty("Shizuku连接断开");}});
 private ServiceConnection connection;
 private ServiceConnection newConnection(long owner){return new ServiceConnection(){
  public void onServiceConnected(ComponentName n,IBinder b){main.post(()->{if(closed||!started||owner!=generation)return;reader=IUltraDataService.Stub.asInterface(b);status="读取真实车况…";});}
  public void onServiceDisconnected(ComponentName n){main.post(()->{if(closed||!started||owner!=generation)return;release();nextBindAt=SystemClock.elapsedRealtime()+2000;empty("只读服务已断开，正在重试");});}
 };}

 private UltraEngine(Context c){context=c;projectionMode=UltraPreferences.outputMode(c);projectionEnabled=projectionMode!=UltraOutputMode.OFF;dashboard=new UltraDashboardView(c);covers=new UltraCoverLoader(dashboard);args=new Shizuku.UserServiceArgs(new ComponentName(c,UltraDataService.class)).daemon(false).processNameSuffix("ultra-data").debuggable(false).version(31);frames=new UltraFrameServer(dashboard,()->started&&!closed&&projectionEnabled&&projectionMode==UltraOutputMode.ULTRA&&dashboard.projectionReady());Shizuku.addBinderReceivedListenerSticky(arrived);Shizuku.addBinderDeadListener(died);}
 public void start(){if(closed)return;UltraMapBuffers.begin();started=true;nextBindAt=0;bind();main.removeCallbacks(poll);main.post(poll);com.shilapi.xcertplay.UltraMapRelay.resume();}
 private void bind(){if(!started||closed||bound||SystemClock.elapsedRealtime()<nextBindAt)return;nextBindAt=SystemClock.elapsedRealtime()+2000;if(FactoryRootClient.selected(context)){bound=true;long owner=generation;io.execute(()->{try{FactoryRootClient client=FactoryRootClient.connect(context);main.post(()->{if(closed||!started||owner!=generation){client.close();return;}rootReader=client;reader=client;status="原车权限 · 读取真实车况…";});}catch(Exception e){main.post(()->{if(!closed&&started&&owner==generation){bound=false;nextBindAt=SystemClock.elapsedRealtime()+10000;empty("原车读取服务不可用，可在设置改用 Shizuku");}});}});return;}try{if(!Shizuku.pingBinder()){empty("等待Shizuku运行");return;}if(Shizuku.checkSelfPermission()!=PackageManager.PERMISSION_GRANTED){empty("请点击授权并允许Shizuku");return;}bound=true;long owner=generation;connection=newConnection(owner);Shizuku.bindUserService(args,connection);main.postDelayed(()->{if(!closed&&started&&bound&&reader==null&&owner==generation){release();empty("只读服务连接超时");}},12000);}catch(Throwable e){release();empty("只读服务连接失败");}}
 private final Runnable poll=new Runnable(){public void run(){if(!started||closed)return;if(reader==null)bind();dashboard.refreshTheme();boolean popupNight=dashboard.nightMode();com.shilapi.xcertplay.media.CarPlayNowPlayingSummary media=com.shilapi.xcertplay.media.CarPlayNowPlayingView.current();dashboard.navigation(com.shilapi.xcertplay.media.CarPlayRouteGuidanceView.current());dashboard.media(media.getTitle(),media.getArtist(),media.getPositionMillis(),media.getDurationMillis(),media.getPlaying());covers.submit(media.getArtworkKey(),media.getArtworkBytes());IUltraDataService target=reader;long owner=generation;boolean project=projectionEnabled&&(projectionMode==UltraOutputMode.MAP||outputHealth.outputActive(dashboard.projectionReady(),SystemClock.elapsedRealtime(),dashboard.themeTransitionDeadline()));if(target!=null&&!pending.getAndSet(true))io.execute(()->{try{target.setPopupTheme(popupNight);target.setProjectionMode(projectionMode);target.setProjectionActive(project&&projectionEnabled&&started&&!closed&&owner==generation);if(project&&restartRequested&&owner==generation){restartRequested=false;target.restartProjection();}String text=target.snapshot();JSONObject data=new JSONObject(text);if(data.optInt("schema")!=1||!"vehicle".equals(data.optString("source"))||(data.optInt("uid",-1)!=0&&data.optInt("uid",-1)!=2000))throw new SecurityException();main.post(()->{if(!closed&&started&&owner==generation){latest=text;projectionState=data.optString("projection","");received=SystemClock.elapsedRealtime();dashboard.accept(data);status=data.optBoolean("connected")?"真实车况已连接":data.optString("error","接口不可用");}});}catch(Throwable e){main.post(()->{if(!closed&&started&&owner==generation){if(rootReader!=null){release();nextBindAt=SystemClock.elapsedRealtime()+2000;}empty("读取服务未返回有效数据");}});}finally{pending.set(false);}});main.postDelayed(this,300);}};
 private void empty(String message){projectionState="";try{JSONObject f=new JSONObject().put("schema",1).put("source","vehicle").put("connected",false).put("error",message).put("fields",new JSONObject());latest=f.toString();received=SystemClock.elapsedRealtime();dashboard.accept(f);status=message;}catch(Exception ignored){}}
 private void release(){generation++;reader=null;FactoryRootClient ownedRoot=rootReader;rootReader=null;if(ownedRoot!=null)ownedRoot.close();ServiceConnection owned=connection;connection=null;try{if(owned!=null)Shizuku.unbindUserService(args,owned,true);}catch(Throwable ignored){}bound=false;}
 public void stop(){started=false;restartRequested=false;outputHealth.reset();release();main.removeCallbacks(poll);dashboard.map(null,0);covers.clear();dashboard.media("","",0,0,false);dashboard.navigation(new com.shilapi.xcertplay.iap2.message.RouteGuidanceSummary());empty("读取已停止");com.shilapi.xcertplay.UltraMapRelay.pause();UltraMapBuffers.clear();}
 public void setProjectionEnabled(boolean enabled){projectionEnabled=enabled;if(!enabled){outputHealth.reset();dashboard.map(null,0);IUltraDataService target=reader;long owner=generation;if(target!=null&&!io.isShutdown())io.execute(()->{try{if(owner==generation&&!projectionEnabled)target.setProjectionActive(false);}catch(Exception ignored){}});}else if(started&&!closed)com.shilapi.xcertplay.UltraMapRelay.resume();}
 public void setProjectionMode(int mode){projectionMode=UltraOutputMode.checked(mode);setProjectionEnabled(mode!=UltraOutputMode.OFF);if(mode!=UltraOutputMode.ULTRA){com.shilapi.xcertplay.UltraMapRelay.pause();dashboard.map(null,0);}else if(started&&!closed)com.shilapi.xcertplay.UltraMapRelay.resume();}
 public boolean ultraMode(){return projectionEnabled&&projectionMode==UltraOutputMode.ULTRA;}
 public void selectNativeReader(boolean selected){FactoryRootClient.select(context,selected);release();nextBindAt=0;if(started&&!closed)bind();}
 public void restartOutput(){restartRequested=true;if(started&&!closed)com.shilapi.xcertplay.UltraMapRelay.resume();}
 public boolean projectionEnabled(){return projectionEnabled;}
 public String projectionStatus(){return projectionState;}
 public boolean started(){return started&&!closed;}
 public void map(BitmapWrapper item){if(closed||!started||!projectionEnabled||projectionMode!=UltraOutputMode.ULTRA){UltraMapBuffers.release(item.bitmap);return;}dashboard.map(item.bitmap,item.sequence);}
 public static final class BitmapWrapper {public final android.graphics.Bitmap bitmap;public final long sequence;public BitmapWrapper(android.graphics.Bitmap b,long s){bitmap=b;sequence=s;}}
 public JSONObject snapshot(){try{return new JSONObject(latest).put("package","com.heavendoor.opultra.carplay").put("appVersion","0.6.7").put("readerBackend",rootReader!=null?"factory_root":"shizuku").put("sinceReceivedMs",received==0?-1:SystemClock.elapsedRealtime()-received).put("display",dashboard.display()).put("frameServer",frames.status()).put("frameExport",frames.diagnostics());}catch(Exception e){return new JSONObject();}}
 public void close(){if(closed)return;stop();closed=true;covers.close();frames.close();dashboard.release();Shizuku.removeBinderReceivedListener(arrived);Shizuku.removeBinderDeadListener(died);io.shutdownNow();synchronized(UltraEngine.class){if(instance==this)instance=null;}}
}
